// A very basic evaluator for simple arithmetic expressions
fn eval_basic_expression(expression: &str) -> Result<f64, &'static str> {
    let tokens: Vec<&str> = expression.split_whitespace().collect();
    if tokens.len() < 3 {
        return Err("Invalid expression");
    }

    let left: f64 = tokens[0].parse().map_err(|_| "Invalid number")?;
    let operator = tokens[1];
    let right: f64 = tokens[2].parse().map_err(|_| "Invalid number")?;

    match operator {
        "+" => Ok(left + right),
        "-" => Ok(left - right),
        "*" => Ok(left * right),
        "/" => {
            if right == 0.0 {
                Err("Division by zero")
            } else {
                Ok(left / right)
            }
        }
        _ => Err("Invalid operator"),
    }
}

